head.script:
// 데이터/옵션 분리: JSON 은 순수 데이터만, 아래 type+옵션은 스크립트가 보유 → 렌더시 조합
scwin.CHART_TYPE = "ontology";                    // 차트 타입 (스크립트)
scwin.CHART_DATA_URL ="/ui/sample/SBChart/GRAPH/data/GRAPH.json";             // 순수 데이터 JSON (type 없음)
scwin.CHART_CONFIG = {
  "extend": {   // 차트별 세부 옵션
    "ontology": {   // 온톨로지 전용 옵션
      "dragable": true,   // 드래그 가능
      "showText": true,   // 텍스트 표시
      "marginBoundary": 60,
      "exceptRadiusLine": true,
      "linkStyle": {   // 링크 스타일
        "strokeColor": "black"   // 선 색
      },
      "circleStyle": {   // 원 스타일
        "strokeColor": "black",   // 선 색
        "color": "dodgerblue"   // 색상 설정
      },
      "collisionRadius": 50,
      "textFormat": function(data) {
        return data.name+'\n('+data.value+')';
      }
    }
  },
  "dataOpts": {   // 데이터 레벨 옵션(keys/labels 등)
    "keys": {   // 데이터 필드 매핑
      "x": "x",
      "value": [   // 값 필드
        {
          "y": "y",
          "value": "value"   // 값 필드
        }
      ]
    }
  }
};               // 옵션(global/axis/extend…) + dataOpts(keys/labels…)

scwin.onpageload = async function () {
    var res = await $c.sbm.executeDynamic({ id: "sbm_sbchart", action: scwin.CHART_DATA_URL, method: "get", mediatype: "application/json", mode: "asynchronous", isProcessMsg: false });
    var data = res.responseJSON;
    $c.ext.drawChartData(scwin.CHART_TYPE, data, chartWrap, scwin.CHART_CONFIG);
};
